#!/data/data/com.termux/files/usr/bin/bash
# stage_engine_inputs.sh — stage the child-forge inputs that must NOT live in the repo.
#
# ChimeraBuilder.forgeChimera reads five files from assets/engine/ at runtime:
#   android.jar                platform classes aapt2 links the child manifest against
#   template.dex               the child's classes.dex (GENERATED by build.sh step 5b)
#   AndroidManifest.tpl.xml    the child manifest template (IN THE REPO — not staged here)
#   release_key                PKCS#8 DER RSA private key  (SECRET — never commit)
#   release_cert               X.509 DER certificate       (SECRET — never commit)
#
# This script stages android.jar from the device's own SDK and generates the signing pair.
# Run it ON THE PHONE, from the project root, before the first forge. Idempotent: existing
# files are left alone unless --force is given. Gradle-free (SPI-1). Read-only elsewhere.
#
#   bash tools/stage_engine_inputs.sh [--force]
#
# The repo's verify_no_signing_material.sh must stay green: release_key/release_cert are
# listed in .gitignore and the source packager skips them.

set -uo pipefail
umask 077

FORCE=0
[ "${1:-}" = "--force" ] && FORCE=1

ROOT="$(pwd)"
ENGINE="$ROOT/app/src/main/assets/engine"
[ -d "$ENGINE" ] || { echo "DEFICITS: {(M1, \"run from the project root; $ENGINE not found\")}"; exit 1; }

say(){ printf '  %s\n' "$*"; }
die(){ printf 'DEFICITS: {(%s, "%s")}\n' "$1" "$2"; exit 1; }

echo "== staging child-forge inputs into assets/engine =="

# ── 1. android.jar — find the device's own platform jar ────────────────────────
if [ -f "$ENGINE/android.jar" ] && [ "$FORCE" = 0 ]; then
  say "android.jar        already present ($(du -h "$ENGINE/android.jar" | cut -f1))"
else
  AJ=""
  for c in \
      "${ANDROID_JAR:-}" \
      "$PREFIX/share/java/android.jar" \
      "$HOME/android-sdk/platforms/android-34/android.jar" \
      "$HOME/android-sdk/platforms/android-35/android.jar" \
      /data/data/com.termux/files/usr/opt/android-sdk/platforms/android-34/android.jar; do
    [ -n "$c" ] && [ -r "$c" ] && { AJ="$c"; break; }
  done
  if [ -z "$AJ" ]; then
    # last resort: aapt2 ships android.jar under Termux's android-sdk package
    AJ=$(find /data/data/com.termux "$HOME" -maxdepth 6 -name android.jar 2>/dev/null | head -1)
  fi
  if [ -n "$AJ" ]; then
    cp "$AJ" "$ENGINE/android.jar"
    say "android.jar        staged from $AJ ($(du -h "$ENGINE/android.jar" | cut -f1))"
  else
    say "android.jar        NOT FOUND — install the platform: pkg install android-sdk-platform-tools (or set ANDROID_JAR)"
  fi
fi

# ── 2. signing pair — generate only if absent (rotation is a separate, deliberate act) ──
if [ -f "$ENGINE/release_key" ] && [ -f "$ENGINE/release_cert" ] && [ "$FORCE" = 0 ]; then
  say "release_key/cert   already present"
else
  command -v openssl >/dev/null 2>&1 || die M1 "openssl missing (pkg install openssl-tool)"
  TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
  openssl req -x509 -newkey rsa:2048 -nodes \
    -keyout "$TMP/key.pem" -out "$TMP/cert.pem" -days 10000 \
    -subj "/CN=Darkith Forge/O=Darkith/C=PH" >/dev/null 2>&1 || die M1 "openssl keygen failed"
  # ApkSignerRunner expects PKCS#8 DER private key and DER X.509 cert.
  openssl pkcs8 -topk8 -nocrypt -in "$TMP/key.pem" -outform DER -out "$ENGINE/release_key" 2>/dev/null \
    || die M1 "pkcs8 conversion failed"
  openssl x509 -in "$TMP/cert.pem" -outform DER -out "$ENGINE/release_cert" 2>/dev/null \
    || die M1 "cert conversion failed"
  say "release_key/cert   generated (PKCS#8 DER + DER X.509)"
fi

# ── 3. template.dex is generated by build.sh; warn if missing ──────────────────
if [ -f "$ENGINE/template.dex" ]; then
  say "template.dex       present ($(du -h "$ENGINE/template.dex" | cut -f1))"
else
  say "template.dex       MISSING — run: bash build.sh . <App> <pkg>  (step 5b generates it)"
fi
[ -f "$ENGINE/AndroidManifest.tpl.xml" ] && say "manifest template  present" || say "manifest template  MISSING (should be in the repo)"

echo "== done =="
